function sinDescuento(importe) {
    return importe;
}

function diezPorCiento(importe) {
    return Math.floor((importe * 90) / 100);
}

function total(importeCentavos, politica) {
    if (importeCentavos < 0) {
        throw new Error("Importe negativo");
    }
    return politica(importeCentavos);
}

console.log(total(1000, sinDescuento));
console.log(total(1000, diezPorCiento));
